package de.kopfzentrum.gam.communication;
import de.kopfzentrum.gam.auth.AuthenticatedUser;import org.springframework.http.HttpStatus;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.List;
@RestController @RequestMapping("/api/communication/workflow") public class CommunicationWorkflowController{private final CommunicationWorkflowRepository repo;public CommunicationWorkflowController(CommunicationWorkflowRepository repo){this.repo=repo;}@GetMapping public List<CommunicationWorkflowItem> list(@RequestParam(required=false)String q,@RequestParam(required=false)String status,@RequestParam(required=false)String responsible,@AuthenticationPrincipal AuthenticatedUser u){req(u);return repo.list(q,status,responsible);}@PostMapping public CommunicationWorkflowItem create(@RequestBody CommunicationWorkflowRequest r,@AuthenticationPrincipal AuthenticatedUser u){req(u);return repo.create(r,u.getUsername());}@PutMapping("/{id}") public CommunicationWorkflowItem update(@PathVariable long id,@RequestBody CommunicationWorkflowRequest r,@AuthenticationPrincipal AuthenticatedUser u){req(u);return repo.update(id,r,u.getUsername());}@DeleteMapping("/{id}") public void delete(@PathVariable long id,@AuthenticationPrincipal AuthenticatedUser u){req(u);repo.delete(id);}private void req(AuthenticatedUser u){if(u==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN);}}
